            <svg width="18" height="18" viewBox="0 0 18 18" fill="none" class="input-icon">
              <rect x="2" y="4" width="14" height="10" rx="2" stroke="#999" stroke-width="1.5" />
              <path d="M2 6l7 5 7-5" stroke="#999" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
            </svg>
            <input
