        <!-- 密码 -->
        <div class="form-group">
          <label for="password">密码 <span class="required">*</span></label>
          <div class="input-wrapper" :class="{ error: errors.password }">
            <svg width="18" height="18" viewBox="0 0 18 18" fill="none" class="input-icon">
