<script setup>
/**
 * RegisterView.vue - 注册页面
 *
 * 功能说明：
 * - 居中卡片布局，带装饰性背景
 * - 用户名/邮箱/密码/确认密码表单
 * - 完整的表单验证（非空、最小长度、邮箱格式、密码一致性）
 * - 密码显示/隐藏切换
 * - 注册按钮调用 store.dispatch('register')
 * - 错误提示显示
 * - 跳转到登录的链接
 */
import { ref, reactive } from 'vue'
import { useStore } from 'vuex'
import { useRouter } from 'vue-router'
import LoadingSpinner from '@/components/LoadingSpinner.vue'

// 获取 Vuex store 和 router 实例
const store = useStore()
const router = useRouter()

// ==================== 响应式状态 ====================

/** 表单数据 */
const form = reactive({
  username: '',
  email: '',
  password: '',
  confirmPassword: ''
})

/** 表单错误信息 */
const errors = reactive({
  username: '',
  email: '',
  password: '',
  confirmPassword: ''
})

/** 是否显示密码 */
const showPassword = ref(false)
/** 是否显示确认密码 */
const showConfirmPassword = ref(false)
/** 注册错误信息 */
const registerError = ref('')
/** 是否正在提交 */
const submitting = ref(false)

// ==================== 验证规则 ====================

/** 邮箱正则表达式 */
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

/** 字段验证规则 */
const validationRules = {
  username: [
    { required: true, message: '请输入用户名' },
    { min: 3, message: '用户名至少3个字符' }
  ],
  email: [
    { required: true, message: '请输入邮箱地址' },
    { pattern: emailRegex, message: '请输入有效的邮箱地址' }
  ],
  password: [
    { required: true, message: '请输入密码' },
    { min: 6, message: '密码至少6个字符' }
  ],
  confirmPassword: [
    { required: true, message: '请确认密码' },
    {
      validator: (value) => value === form.password,
      message: '两次输入的密码不一致'
    }
  ]
}

// ==================== 方法 ====================

/**
 * 验证单个字段
 * @param {string} field - 字段名
 * @returns {boolean} 验证是否通过
 */
const validateField = (field) => {
  const value = form[field]?.trim() || ''
  const rules = validationRules[field]
  errors[field] = ''
  for (const rule of rules) {
    if (rule.required && !value && value !== form[field]) {
      errors[field] = rule.message
      return false
    }
    if (rule.min && value.length < rule.min) {
      errors[field] = rule.message
      return false
    }
    if (rule.pattern && !rule.pattern.test(value)) {
      errors[field] = rule.message
      return false
    }
    if (rule.validator && !rule.validator(value)) {
      errors[field] = rule.message
      return false
    }
  }
  return true
}

/**
 * 验证整个表单
 * @returns {boolean} 验证是否通过
 */
const validateForm = () => {
  let valid = true
  valid = validateField('username') && valid
  valid = validateField('email') && valid
  valid = validateField('password') && valid
  valid = validateField('confirmPassword') && valid
  return valid
}

/**
 * 处理注册提交
 */
const handleRegister = async () => {
  // 先验证表单
  if (!validateForm()) return

  registerError.value = ''
  submitting.value = true

  try {
    await store.dispatch('register', {
      username: form.username.trim(),
      email: form.email.trim(),
      password: form.password
    })
    // 注册成功，跳转到登录页
    router.push('/login')
  } catch (err) {
    registerError.value = err.message || '注册失败，请稍后重试'
  } finally {
    submitting.value = false
  }
}
</script>

